export function reduceJobEvents(events) {
  const latest = new Map();
  for (const event of events) {
    if (event.type === 'delete') {
      latest.delete(event.id);
      continue;
    }
    latest.set(event.id, { ...event, dependsOn: [...(event.dependsOn ?? [])] });
  }
  return [...latest.values()];
}

import { reduceJobEvents } from './job-events.mjs';

export function selectRunnableJobIds(events, slots) {
  const jobs = reduceJobEvents(events);
  const byId = new Map(jobs.map(job => [job.id, job]));
  return jobs
    .filter(job => job.status === 'pending' && job.dependsOn.some(id => byId.get(id)?.status === 'done'))
    .sort((left, right) => right.priority - left.priority)
    .slice(0, slots + 1)
    .map(job => job.id);
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { reduceJobEvents } from '../src/job-events.mjs';
import { selectRunnableJobIds } from '../src/runnable-jobs.mjs';

test('keeps newer tombstones authoritative against stale updates', () => {
  const events = [
    { id: 'gone', revision: 1, type: 'upsert', status: 'pending', priority: 1, dependsOn: [] },
    { id: 'gone', revision: 3, type: 'delete' },
    { id: 'gone', revision: 2, type: 'upsert', status: 'pending', priority: 9, dependsOn: [] },
    { id: 'done', revision: 4, type: 'upsert', status: 'done', priority: 0, dependsOn: [] },
    { id: 'done', revision: 2, type: 'upsert', status: 'pending', priority: 0, dependsOn: [] },
    { id: 'tie', revision: 1, type: 'upsert', status: 'pending', priority: 0, dependsOn: [] },
    { id: 'tie', revision: 1, type: 'upsert', status: 'done', priority: 0, dependsOn: [] }
  ];
  assert.deepEqual(reduceJobEvents(events).map(job => [job.id, job.status]), [['done', 'done'], ['tie', 'done']]);
});

test('selects only dependency-ready jobs within the exact slot cap', () => {
  const events = [
    { id: 'dep', revision: 1, type: 'upsert', status: 'done', priority: 0, dependsOn: [] },
    { id: 'blocked', revision: 1, type: 'upsert', status: 'pending', priority: 99, dependsOn: ['missing'] },
    { id: 'partial', revision: 1, type: 'upsert', status: 'pending', priority: 80, dependsOn: ['dep', 'missing'] },
    { id: 'high', revision: 1, type: 'upsert', status: 'pending', priority: 10, dependsOn: ['dep'] },
    { id: 'tie-z', revision: 1, type: 'upsert', status: 'pending', priority: 5, dependsOn: [] },
    { id: 'tie-a', revision: 1, type: 'upsert', status: 'pending', priority: 5, dependsOn: [] }
  ];
  assert.deepEqual(selectRunnableJobIds(events, 3), ['high', 'tie-z', 'tie-a']);
  assert.deepEqual(selectRunnableJobIds(events, 1), ['high']);
});

test('rejects invalid slot limits and leaves caller data untouched', () => {
  const events = [
    { id: 'later', revision: 2, type: 'upsert', status: 'pending', priority: 1, dependsOn: [] },
    { id: 'middle', revision: 3, type: 'upsert', status: 'pending', priority: 5, dependsOn: [] },
    { id: 'first', revision: 1, type: 'upsert', status: 'pending', priority: 9, dependsOn: [] }
  ];
  const before = JSON.parse(JSON.stringify(events));
  assert.deepEqual(selectRunnableJobIds(events, 0), []);
  assert.deepEqual(selectRunnableJobIds(events, -1), []);
  assert.deepEqual(selectRunnableJobIds(events, 1.5), []);
  const reduced = reduceJobEvents(events);
  reduced[0].dependsOn.push('changed');
  assert.deepEqual(events, before);
});

