export function reduceJobEvents(events) {
  const latest = new Map();
  for (const [index, event] of events.entries()) {
    const current = latest.get(event.id);
    if (!current || event.revision >= current.event.revision) {
      latest.set(event.id, {
        event: { ...event, dependsOn: [...(event.dependsOn ?? [])] },
        firstSeen: current?.firstSeen ?? index
      });
    }
  }
  return [...latest.values()]
    .filter(({ event }) => event.type !== 'delete')
    .sort((left, right) => left.firstSeen - right.firstSeen)
    .map(({ event }) => event);
}

import { reduceJobEvents } from './job-events.mjs';

export function selectRunnableJobIds(events, slots) {
  if (!Number.isInteger(slots) || slots <= 0) return [];
  const jobs = reduceJobEvents(events);
  const byId = new Map(jobs.map(job => [job.id, job]));
  const firstSeen = new Map(jobs.map((job, index) => [job.id, index]));
  return jobs
    .filter(job => job.status === 'pending' && job.dependsOn.every(id => byId.get(id)?.status === 'done'))
    .sort((left, right) => right.priority - left.priority || firstSeen.get(left.id) - firstSeen.get(right.id))
    .slice(0, slots)
    .map(job => job.id);
}
